import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"MCP 工具","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/mcp-tools/overview.md","filePath":"zh-CN/mcp-tools/overview.md","lastUpdated":1784903584000}'),n={name:"zh-CN/mcp-tools/overview.md"};function a(s,t,r,i,l,p){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="mcp-工具" tabindex="-1">MCP 工具 <a class="header-anchor" href="#mcp-工具" aria-label="Permalink to &quot;MCP 工具&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>swag2mcp 提供 <strong>19 个 MCP 工具</strong>，让 LLM 智能体通过模型上下文协议完全访问你的 API。这些工具涵盖完整的工作流程：发现可用的 API、导航 spec 层次结构、搜索和检查端点、执行 API 调用以及处理大响应。</p><h3 id="工具解决的问题" tabindex="-1">工具解决的问题 <a class="header-anchor" href="#工具解决的问题" aria-label="Permalink to &quot;工具解决的问题&quot;">​</a></h3><ul><li><strong>发现</strong> — LLM 无需事先知道 ID 即可找到 spec、collection 和标签</li><li><strong>导航</strong> — 在结构化层次结构中从 spec → collection → tag → endpoint 深入</li><li><strong>搜索</strong> — 当你没有 ID 时，跨所有端点进行全文搜索</li><li><strong>检查</strong> — 在调用之前获取完整的 OpenAPI 操作对象</li><li><strong>执行</strong> — 使用自动认证调用真实的 API</li><li><strong>大响应处理</strong> — 概述、压缩和切片不适合内联的过大响应</li></ul><h3 id="只读-vs-可变" tabindex="-1">只读 vs 可变 <a class="header-anchor" href="#只读-vs-可变" aria-label="Permalink to &quot;只读 vs 可变&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>数量</th><th>工具</th></tr></thead><tbody><tr><td><strong>只读</strong></td><td>17</td><td>所有发现、端点、搜索、检查、信息和响应工具</td></tr><tr><td><strong>可变</strong></td><td>2</td><td><code>invoke</code>（发出真实 HTTP 调用）、<code>auth</code>（检索令牌）</td></tr></tbody></table><p>只读工具在 MCP 协议中标记为 <code>ReadOnlyHint=true</code> 和 <code>IdempotentHint=true</code>，向 LLM 表明它们可以安全调用，没有副作用。</p><h3 id="错误处理" tabindex="-1">错误处理 <a class="header-anchor" href="#错误处理" aria-label="Permalink to &quot;错误处理&quot;">​</a></h3><p>所有工具以结构化的 <code>LLMError</code> 对象返回错误，包含机器可读的代码和人类可读的消息，解释出了什么问题以及下一步该怎么做：</p><table tabindex="0"><thead><tr><th>错误代码</th><th>含义</th></tr></thead><tbody><tr><td><code>validation_failed</code></td><td>无效输入（错误的 ID 格式、缺少必需字段）</td></tr><tr><td><code>not_found</code></td><td>在索引或工作区中未找到实体</td></tr><tr><td><code>rate_limit</code></td><td>10 秒内对同一端点的第二次 <code>invoke</code> 调用</td></tr><tr><td><code>invoke_error</code></td><td>HTTP 调用失败、下载失败</td></tr><tr><td><code>auth_error</code></td><td>认证令牌检索失败</td></tr><tr><td><code>config_error</code></td><td>配置文件加载或保存失败</td></tr><tr><td><code>parse_error</code></td><td>规范文件解析失败</td></tr></tbody></table><h2 id="分类" tabindex="-1">分类 <a class="header-anchor" href="#分类" aria-label="Permalink to &quot;分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>工具</th><th>描述</th></tr></thead><tbody><tr><td><strong>发现</strong></td><td><code>spec_list</code>、<code>spec_by_id</code>、<code>collection_by_spec</code>、<code>collection_by_id</code>、<code>tag_by_spec</code>、<code>tag_by_collection</code>、<code>tag_by_id</code></td><td>导航 spec 层次结构：查找 spec、collection 和标签</td></tr><tr><td><strong>端点</strong></td><td><code>endpoint_by_spec</code>、<code>endpoint_by_collection</code>、<code>endpoint_by_tag</code>、<code>endpoint_by_id</code></td><td>在层次结构的不同级别查看端点</td></tr><tr><td><strong>执行</strong></td><td><code>search</code>、<code>inspect</code>、<code>invoke</code></td><td>搜索、检查完整契约和调用 API</td></tr><tr><td><strong>实用工具</strong></td><td><code>auth</code>、<code>info</code>、<code>response_outline</code>、<code>response_compress</code>、<code>response_slice</code></td><td>认证令牌、运行时信息和大响应处理</td></tr><tr><td><strong>技能</strong></td><td><a href="/mcp-tools/skills">格式化指南</a></td><td>自定义工具响应的显示方式</td></tr></tbody></table><h2 id="完整列表" tabindex="-1">完整列表 <a class="header-anchor" href="#完整列表" aria-label="Permalink to &quot;完整列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>描述</th></tr></thead><tbody><tr><td><code>spec_list</code></td><td>列出工作区中的所有 API 规范</td></tr><tr><td><code>spec_by_id</code></td><td>获取包含 collection 的详细 spec 信息</td></tr><tr><td><code>collection_by_spec</code></td><td>列出 spec 中的 collection</td></tr><tr><td><code>collection_by_id</code></td><td>获取包含标签的 collection 详情</td></tr><tr><td><code>tag_by_spec</code></td><td>列出 spec 中的所有标签</td></tr><tr><td><code>tag_by_collection</code></td><td>列出 collection 中的标签</td></tr><tr><td><code>tag_by_id</code></td><td>获取标签详情（ID、标题、方法计数）</td></tr><tr><td><code>endpoint_by_spec</code></td><td>列出 spec 中的所有端点</td></tr><tr><td><code>endpoint_by_collection</code></td><td>列出 collection 中的端点</td></tr><tr><td><code>endpoint_by_tag</code></td><td>列出标签中的端点</td></tr><tr><td><code>endpoint_by_id</code></td><td>快速端点摘要（方法、路径、摘要）</td></tr><tr><td><code>search</code></td><td>跨所有端点的全文搜索</td></tr><tr><td><code>inspect</code></td><td>完整的 OpenAPI 操作详情（参数、模式）</td></tr><tr><td><code>invoke</code></td><td>执行真实的 API 调用</td></tr><tr><td><code>auth</code></td><td>获取 spec 的认证令牌或头</td></tr><tr><td><code>info</code></td><td>运行时信息（版本、spec、配置）</td></tr><tr><td><code>response_outline</code></td><td>大响应文件的结构摘要</td></tr><tr><td><code>response_compress</code></td><td>压缩大响应以适应内联</td></tr><tr><td><code>response_slice</code></td><td>提取大响应的片段</td></tr></tbody></table><h2 id="导航层次结构" tabindex="-1">导航层次结构 <a class="header-anchor" href="#导航层次结构" aria-label="Permalink to &quot;导航层次结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec_list</span></span>
<span class="line"><span>  └── spec_by_id(id)</span></span>
<span class="line"><span>        └── collection_by_spec(specId)</span></span>
<span class="line"><span>              └── collection_by_id(id)</span></span>
<span class="line"><span>                    └── tag_by_collection(collectionId)</span></span>
<span class="line"><span>                          └── tag_by_id(id)</span></span>
<span class="line"><span>                                └── endpoint_by_tag(tagId)</span></span>
<span class="line"><span>                                      └── endpoint_by_id(id)</span></span>
<span class="line"><span>                                            └── inspect(endpointId)</span></span>
<span class="line"><span>                                                  └── invoke(endpointId)</span></span></code></pre></div><p>当你没有 ID 时，使用 <code>search</code> 按查询查找端点。当 <code>invoke</code> 返回 <code>fileRef</code>（响应太大）时，使用 <code>response_outline</code> → <code>response_compress</code> 或 <code>response_slice</code> 探索数据。</p>`,18)])])}const b=d(n,[["render",a]]);export{h as __pageData,b as default};
